#include "Renderer/Nature/TerrainNeighbors.h"
namespace Stardust {
void TerrainNeighbors::AutoConnect(Scene& scene){auto& reg=scene.Reg();reg.Each<TerrainComponent>([&](EntityID a,TerrainComponent& first){first.neighbors={};auto p=glm::vec3(scene.GetWorldMatrix(a)[3]);reg.Each<TerrainComponent>([&](EntityID b,TerrainComponent& second){if(a==b||std::abs(first.settings.size-second.settings.size)>.01f)return;auto d=glm::vec3(scene.GetWorldMatrix(b)[3])-p;float size=first.settings.size,tolerance=std::max(.01f,size*.0001f);int side=-1;if(std::abs(d.z)<tolerance&&std::abs(std::abs(d.x)-size)<tolerance)side=d.x<0?0:1;if(std::abs(d.x)<tolerance&&std::abs(std::abs(d.z)-size)<tolerance)side=d.z<0?2:3;if(side>=0)first.neighbors[side]=reg.Get<IDComponent>(b).uuid;});});}
int TerrainNeighbors::Stitch(Scene& scene,EntityID entity){auto* terrain=scene.Reg().TryGet<TerrainComponent>(entity);if(!terrain)return 0;auto data=TerrainData::Find(scene.Reg().Get<IDComponent>(entity).uuid);if(!data)return 0;int count=0;auto origin=scene.GetWorldMatrix(entity)[3];for(int side=0;side<4;++side)if(auto other=scene.FindByUUID(terrain->neighbors[side])){auto next=TerrainData::Find(terrain->neighbors[side]);if(next&&data->StitchEdge(*next,side,scene.GetWorldMatrix(other)[3].y-origin.y))++count;}return count;}
}
